def transform(grid):
    from collections import Counter
    h,w=len(grid),len(grid[0])
    rs=[r for r in range(h) if all(x==0 for x in grid[r])]
    cs=[c for c in range(w) if all(grid[r][c]==0 for r in range(h))]
    panels=[]
    if rs:
        bounds=[-1]+rs+[h]
        for a,b in zip(bounds,bounds[1:]):
            if b>a+1: panels.append(grid[a+1:b])
    elif cs:
        bounds=[-1]+cs+[w]
        for a,b in zip(bounds,bounds[1:]):
            if b>a+1: panels.append([row[a+1:b] for row in grid])
    else: return [[0]]
    shapes=[]
    for p in panels:
        bg=Counter(v for row in p for v in row).most_common(1)[0][0]
        pts=[(r,c) for r,row in enumerate(p) for c,v in enumerate(row) if v!=bg and v!=0]
        if not pts: return [[0]]
        r0=min(r for r,c in pts); r1=max(r for r,c in pts)
        c0=min(c for r,c in pts); c1=max(c for r,c in pts)
        shapes.append([[p[r][c] if p[r][c]!=bg else 0 for c in range(c0,c1+1)] for r in range(r0,r1+1)])
    return shapes[0] if shapes and all(s==shapes[0] for s in shapes) else [[0]]

